"""image_bvh_intersect_ray / image_bvh64_intersect_ray on triangle nodes against words measured on native RDNA2.

Every expected word below was returned by the instruction itself on an AMD Radeon RX 6800 (gfx1030, AMD Windows
driver 26.11.2, Windows 11, 2026-11-22), through tools/hw_oracle raw kernels (tools/bvh_tri_probe.py builds the same
kernels) that write hand-built 64-byte triangle nodes into memory and trace one ray per case in both forms: the
32-bit node pointer with the descriptor base at the node, and the 64-bit one with base 0. The descriptor is the one
#3567 measured boxes with (w1 bit 31 box sort, w2 = 0xFFFFFFFF, w3 = 0x81000000). Both forms returned the same four
words in every case, wave32 the same as wave64 and NSA address operands the same as contiguous ones. No game data.

The rule the words follow is in the docs/design.md Ray tracing row: the watertight test, with the shear taken from the
direction (the supplied inverse direction is not used); a hit gives k*(T, det, b_i, b_j) and a miss
(copysign(inf, k*det), k*det, k*b_i, k*b_j), k = |d[kz]|^3; no test against t max, t >= 0 tested; zero words +0 and
NaN words 0xFFC00000; a NaN anywhere in the ray or an infinite origin gives (inf, 1, 0, 0); RDNA2's own tie rule on
shared edges and vertices.

Rows: all 308 single-lane rows of the 12 single-lane kernels (fan leaf of the four node types around one vertex,
mirrored and axis-permuted leaves, misses on both sides, the remap byte, t max / t sign / zero area / NaN and inf
inputs, the ray's own NaN / inf / zero / wrong inverse direction, shared edges and vertices), each run in both forms,
and lanes 0, 15, 16, 31, 32 and 63 of the two 64-thread kernels (all 7 cases). Then the 256 rows of the tie kernels
tri_t1..tri_t8 (same driver, same descriptor, 2026-11-23): rays exactly on a shared edge, an outer edge or a vertex
with x, y or z dominant, both windings and both signs of d[kz] (fan, mirrored, rotated in its plane and tilted
leaves, axis and oblique rays), equal |d| components with and without a tie, and 22 repeated #4202 rows as controls.
Every row is asserted.

    python -m unittest discover -s tests/semantic -p "test_image_bvh_tri_hw.py" -v
"""
import unittest

from support import mrt0_words, translate_lines

RAY = 0x1000          # node id (lo, hi), t max, origin, direction, inverse direction: read with s_buffer_load
NODE = 0x2000         # the 64-byte node
PUSH = [RAY, 0, 0x100, 0] + [0] * 28          # V# in s[0:3]: base RAY, num_records 256

