def program(form, nsa):
    """A pixel shader that loads the node id and the ray from memory and exports the instruction's four words."""
    lines = ["s_buffer_load_dwordx16 s[8:23], s[0:3], 0", "s_waitcnt lgkmcnt(0)"]
    if form == "64":
        lines += [f"v_mov_b32_e32 v{1 + i}, s{8 + i}" for i in range(12)]           # v1:v2 node id, v3..v12 ray
        lines += ["s_mov_b32 s4, 0", "s_mov_b32 s5, 0x80000000"]                     # base 0: the id is the address
        regs = [f"v{1 + i}" for i in range(12)]
        op = "image_bvh64_intersect_ray"
    else:
        lines += ["v_mov_b32_e32 v1, s8"] + [f"v_mov_b32_e32 v{2 + i}, s{10 + i}" for i in range(10)]
        lines += [f"s_mov_b32 s4, 0x{NODE >> 8:x}", "s_mov_b32 s5, 0x80000000"]     # base = NODE in 256-byte units
        regs = [f"v{1 + i}" for i in range(11)]
        op = "image_bvh_intersect_ray"
    addr = "[" + ", ".join(regs) + "]" if nsa else f"v[1:{len(regs)}]"
    lines += ["s_mov_b32 s6, -1", "s_mov_b32 s7, 0x81000000",
              f"{op} v[20:23], {addr}, s[4:7]", "exp mrt0 v20, v21, v22, v23 done vm", "s_endpgm"]
    return translate_lines(f"ps_bvh_tri_hw_{form}{'_nsa' if nsa else ''}", lines)


_SPV = {}


def run(form, nsa, node, w15, ntype, ray):
    key = (form, nsa)
    if key not in _SPV:
        _SPV[key] = program(form, nsa)
    nid = (NODE >> 3 | ntype) if form == "64" else ntype
    mem = {RAY + 4 * i: w for i, w in enumerate([nid, 0, *ray, 0, 0, 0, 0])}
    mem.update({NODE + 4 * i: w for i, w in enumerate(NODES[node] + [w15])})
    return list(mrt0_words(_SPV[key], push_constants=PUSH, memory=mem))


def words(ws):
    return " ".join(f"{w:08x}" for w in ws)


class MeasuredTriangleNodes(unittest.TestCase):
    def check(self, rows):
        for kernel, label, node, w15, ntype, ray, hw in rows:
            for form in ("32", "64"):
                with self.subTest(kernel=kernel, case=label, form=form):
                    got = run(form, kernel.endswith("_nsa"), node, w15, ntype, ray)
                    self.assertEqual(words(got), words(hw))

    def test_single_lane_rows(self):
        self.check(ROWS)

    def test_lane_rows(self):
        self.check(LANE_ROWS)

    def test_table(self):
        # a row dropped from the table (or one kernel's rows lost) fails here, not silently
        per = {}
        for kernel, *_ in ROWS:
            per[kernel] = per.get(kernel, 0) + 1
        self.assertEqual(per, {"tri_g1a": 25, "tri_g1a_nsa": 25, "tri_g1a_w64": 25, "tri_g1b": 16, "tri_g1c": 30,
                               "tri_g2a": 32, "tri_g2b": 32, "tri_g2c": 32, "tri_g3a": 24, "tri_g3b": 19,
                               "tri_g4a": 16, "tri_g4b": 32, **{f"tri_t{i}": 32 for i in range(1, 9)}})
        self.assertEqual(len(LANE_ROWS), 2 * 7 * 6)
        self.assertEqual(len({(k, lb) for k, lb, *_ in ROWS}), len(ROWS))


if __name__ == "__main__":
    unittest.main()
